<?php
namespace Tests\Feature;
use App\Domain\Network\Billing\{EntitlementService,SubscriptionService,UsageService};use App\Domain\Network\Billing\Models\{Subscription,UsageEvent};use App\Domain\Network\Catalog\Models\{Module,Plan};use App\Domain\Network\Commerce\{TenantSaasActivationService,TenantSaasOrderService};use App\Domain\Network\Commerce\Models\{NetworkCommercialProduct,TenantSaasOrder,TenantOperationAllowance};use App\Domain\Network\Tenancy\Models\Tenant;use App\Models\User;use Illuminate\Database\Schema\Blueprint;use Illuminate\Support\Facades\{DB,Schema};use Tests\TestCase;
final class ZigoSaasBillingTest extends TestCase{
 protected function setUp():void{parent::setUp();if(DB::connection()->getDriverName()!=='sqlite'||DB::connection()->getDatabaseName()!==':memory:')$this->markTestSkipped('Requires SQLite :memory:.');$this->schema();}
 public function test_catalog_price_is_server_side_order_is_idempotent_and_pending_does_not_activate():void{$p=$this->product('PACK100','OPERATION_PACK',250,100);$s=app(TenantSaasOrderService::class);$a=$s->create($this->tenant,$this->user,$p,'same-key');$b=$s->create($this->tenant,$this->user,$p,'same-key');$this->assertSame($a->id,$b->id);$this->assertSame('250.00',$a->total_amount);$this->expectException(\RuntimeException::class);app(TenantSaasActivationService::class)->activate($a);}
 public function test_approved_pack_adds_allowance_once_without_mutating_usage():void{$sub=$this->subscription();UsageEvent::create(['tenant_id'=>$this->tenant->id,'subscription_id'=>$sub->id,'metric'=>'operations','quantity'=>7,'occurred_at'=>now(),'idempotency_key'=>'before']);$o=$this->paid($this->product('PACK500','OPERATION_PACK',500,500));$activation=app(TenantSaasActivationService::class);$activation->activate($o);$activation->activate($o->fresh());$this->assertSame(1,TenantOperationAllowance::count());$this->assertSame(7,(int)UsageEvent::sum('quantity'));$this->assertSame(800,app(UsageService::class)->limit($this->tenant,'operations',$sub));}
 public function test_approved_module_entitlement_and_plan_renewal_are_idempotent():void{$sub=$this->subscription();$module=Module::create(['code'=>'DRIVER','name'=>'Driver','type'=>'addon','is_active'=>true,'sort_order'=>1]);$p=$this->product('DRIVER-M','MODULE',99);$p->update(['module_id'=>$module->id]);$o=$this->paid($p->fresh());$svc=app(TenantSaasActivationService::class);$svc->activate($o);$svc->activate($o->fresh());$this->assertSame(1,DB::table('network_entitlements')->where('code','DRIVER')->count());$planProduct=$this->product('PLAN-RENEW','PLAN',1000);$planProduct->update(['plan_id'=>$this->plan->id,'billing_type'=>'MONTHLY']);$before=$sub->current_period_end->copy();$svc->activate($this->paid($planProduct->fresh()));$this->assertTrue($sub->fresh()->current_period_end->gt($before));$this->assertSame(1,Subscription::count());}
 public function test_routes_have_no_manual_activation_and_returns_are_get_only():void{$routes=collect(app('router')->getRoutes()->getRoutes());$this->assertFalse($routes->contains(fn($r)=>(str_contains((string)$r->uri(),'saas')&&str_contains((string)$r->uri(),'activate'))||str_contains((string)$r->uri(),'paid=1')));$return=$routes->first(fn($r)=>$r->getName()==='tenant.admin.saas.return');$this->assertSame(['GET','HEAD'],$return->methods());$catalog=$routes->first(fn($r)=>$r->getName()==='network.catalog.store');$this->assertContains('network.superadmin',$catalog->gatherMiddleware());}
 public function test_migration_is_reversible():void{$m=require database_path('migrations/2026_08_15_100000_create_zigo_saas_billing_foundation.php');$m->down();$this->assertFalse(Schema::hasTable('tenant_saas_orders'));}
 private Tenant$tenant;private User$user;private Plan$plan;
 private function schema():void{Schema::create('users',function(Blueprint$t){$t->id();$t->string('name');$t->string('email');$t->string('password');$t->timestamps();});Schema::create('network_tenants',function(Blueprint$t){$t->id();$t->uuid('uuid')->nullable();$t->string('name');$t->string('slug');$t->string('status');$t->unsignedBigInteger('current_plan_id')->nullable();$t->timestamps();});Schema::create('network_modules',function(Blueprint$t){$t->id();$t->string('code');$t->string('name');$t->text('description')->nullable();$t->string('type');$t->boolean('is_active');$t->integer('sort_order');$t->timestamps();});Schema::create('network_plans',function(Blueprint$t){$t->id();$t->string('code');$t->string('name');$t->text('description')->nullable();$t->string('status');$t->decimal('monthly_price',12,2)->nullable();$t->decimal('annual_price',12,2)->nullable();$t->char('currency',3);$t->integer('included_operations')->nullable();$t->timestamps();});Schema::create('network_plan_modules',function(Blueprint$t){$t->id();$t->unsignedBigInteger('plan_id');$t->unsignedBigInteger('module_id');$t->boolean('is_included');$t->integer('limit_value')->nullable();$t->timestamps();});Schema::create('network_subscriptions',function(Blueprint$t){$t->id();$t->uuid('uuid');$t->unsignedBigInteger('tenant_id');$t->unsignedBigInteger('plan_id');$t->string('status');$t->integer('operations_limit')->nullable();foreach(['started_at','current_period_start','current_period_end','trial_ends_at','grace_ends_at','canceled_at','ended_at']as$c)$t->timestamp($c)->nullable();$t->timestamps();});Schema::create('network_entitlements',function(Blueprint$t){$t->id();$t->unsignedBigInteger('subscription_id');$t->unsignedBigInteger('tenant_id');$t->unsignedBigInteger('module_id');$t->string('code');$t->boolean('is_enabled');$t->integer('limit_value')->nullable();$t->string('source');$t->timestamps();$t->unique(['subscription_id','module_id']);$t->unique(['subscription_id','code']);});Schema::create('network_subscription_events',function(Blueprint$t){$t->id();$t->unsignedBigInteger('subscription_id');$t->unsignedBigInteger('tenant_id');$t->unsignedBigInteger('actor_user_id')->nullable();$t->string('event');$t->string('from_status')->nullable();$t->string('to_status')->nullable();$t->json('metadata')->nullable();$t->timestamps();});Schema::create('network_usage_events',function(Blueprint$t){$t->id();$t->uuid('uuid')->nullable();$t->unsignedBigInteger('tenant_id');$t->unsignedBigInteger('subscription_id');$t->string('metric');$t->integer('quantity');$t->string('reference_type')->nullable();$t->string('reference_id')->nullable();$t->string('idempotency_key')->nullable();$t->timestamp('occurred_at');$t->json('metadata')->nullable();$t->timestamp('created_at')->nullable();});$m=require database_path('migrations/2026_08_15_100000_create_zigo_saas_billing_foundation.php');$m->up();$this->user=User::create(['name'=>'Owner','email'=>uniqid().'@test','password'=>'x']);$this->tenant=Tenant::create(['name'=>'RapidGo','slug'=>uniqid('rapid'),'status'=>'active']);$this->plan=Plan::create(['code'=>'LOCAL300','name'=>'Local 300','status'=>'active','monthly_price'=>1000,'currency'=>'MXN','included_operations'=>300]);}
 private function subscription():Subscription{return Subscription::first()??Subscription::create(['tenant_id'=>$this->tenant->id,'plan_id'=>$this->plan->id,'status'=>'active','operations_limit'=>300,'started_at'=>now()->subDay(),'current_period_start'=>now()->subDay(),'current_period_end'=>now()->addMonth()]);}
 private function product(string$code,string$type,float$price,?int$ops=null):NetworkCommercialProduct{return NetworkCommercialProduct::create(['code'=>$code,'name'=>$code,'type'=>$type,'billing_type'=>'ONE_TIME','price'=>$price,'currency'=>'MXN','included_operations'=>$ops,'is_active'=>true]);}
 private function paid(NetworkCommercialProduct$p):TenantSaasOrder{$o=app(TenantSaasOrderService::class)->create($this->tenant,$this->user,$p,(string)\Illuminate\Support\Str::uuid());$o->update(['status'=>'PAID','payment_status'=>'APPROVED']);return$o->fresh();}
}
